@Test
public void escapeString_1_oe() {
    String str = "   +%\r\n\t\b%=;;;   ";
    String expectedStr = "%2b%25%0d%0a%09%08%25%3d%3b%3b%3b";
    String actualStr = Cookie.escape(str);

}

mut_method_definition:
public static String escape(String string) {
        char            c;
        String          s = string.trim();
        int             length = s.length();
        StringBuilder   sb = new StringBuilder(length);
        for (int i = 0; i < length; i += 1) {
            c = s.charAt(i);
            if (c < ' ' || c == '+' || c == '%' || c == '=' || c == ';') {
                sb.append('%');
                sb.append(Character.forDigit((char)((c >>> 4) & 0x0f), 16));
                sb.append(Character.forDigit((char)(c & 0x0f), 16));
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

test_prefix:
@Test
public void unescapeString_1_oe() {
    String str = " +%2b%25%0d%0a%09%08%25%3d%3b%3b%3b+ ";
    String expectedStr = "  +%\r\n\t\b%=;;;  ";
    String actualStr = Cookie.unescape(str);

}

mut_method_definition:
public static String unescape(String string) {
        int length = string.length();
        StringBuilder sb = new StringBuilder(length);
        for (int i = 0; i < length; ++i) {
            char c = string.charAt(i);
            if (c == '+') {
                c = ' ';
            } else if (c == '%' && i + 2 < length) {
                int d = JSONTokener.dehexchar(string.charAt(i + 1));
                int e = JSONTokener.dehexchar(string.charAt(i + 2));
                if (d >= 0 && e >= 0) {
                    c = (char)(d * 16 + e);
                    i += 2;
                }
            }
            sb.append(c);
        }
        return sb.toString();
    }

