public void testIssue682SimilarityOfJSONString_1_oe() {
    JSONObject jo1 = new JSONObject()
            .put("a", new MyJsonString())
            .put("b", 2);
    JSONObject jo2 = new JSONObject()
            .put("a", new MyJsonString())
            .put("b", 2);

