    final String string2 = "HasDifferentRef";
    JSONArray obj1 = new JSONArray()
            .put("abc")
            .put(string1)
            .put(2);

    JSONArray obj2 = new JSONArray()
            .put("abc")
            .put(string1)
            .put(3);

    JSONArray obj3 = new JSONArray()
            .put("abc")
            .put(new String(string1))
            .put(2);

    JSONArray obj4 = new JSONArray()
            .put("abc")
            .put(2.0)
